import os
import posixpath
from urllib.parse import urlparse


def return_url(target):
    """Validate an untrusted redirect target and return a safe local path.

    Safe paths (absolute or relative local paths with no traversal or schemes)
    pass through unchanged. Any suspicious value is rejected and '/' is returned.
    """
    if not isinstance(target, str) or not target:
        return "/"

    # Reject null bytes — a classic injection vector
    if "\x00" in target:
        return "/"

    # Reject absolute URLs (http://, https://, //evil.com, protocol: schemes)
    parsed = urlparse(target)
    if parsed.scheme in ("http", "https", "ftp", "ftps", "mailto", "data", "javascript"):
        return "/"
    if parsed.scheme and parsed.netloc:
        return "/"
    # Reject protocol-relative URLs
    if target.startswith("//"):
        return "/"

    # Normalise the path and ensure no parent-directory traversal survives
    # posixpath.normpath handles Windows-style backslashes too
    norm = posixpath.normpath(target)

    # Reject anything that escapes the current directory
    if norm.startswith(".."):
        return "/"
    if norm.startswith("/.."):
        return "/"
    if norm == "..":
        return "/"

    # Reject paths that contain '..' components after normalisation
    parts = norm.replace("\\", "/").split("/")
    for part in parts:
        if part == "..":
            return "/"

    # Must start with '/' or be a relative path without leading '.'
    if not norm.startswith("/") and not norm.startswith("./"):
        # Allow simple relative paths like "foo" or "foo/bar"
        if any(p == ".." for p in parts):
            return "/"

    return norm

