import os


def archive_path(base, filename):
    if not filename or "\x00" in filename:
        raise ValueError("unsafe filename")
    joined = os.path.join(base, filename)
    real_base = os.path.realpath(base)
    real_joined = os.path.realpath(joined)
    if not real_joined.startswith(real_base + os.sep) and real_joined != real_base:
        raise ValueError("unsafe filename")
    return joined

import os
import pytest
from archives import archive_path


@pytest.fixture
def tmp_base(tmp_path):
    base = tmp_path / "archives" / "2026"
    base.mkdir(parents=True)
    return str(base)


def test_simple_filename(tmp_base):
    assert archive_path(tmp_base, "report.pdf") == os.path.join(tmp_base, "report.pdf")


def test_nested_safe(tmp_base):
    assert archive_path(tmp_base, "sub/report.pdf") == os.path.join(tmp_base, "sub/report.pdf")


def test_dotdot_traversal(tmp_base):
    with pytest.raises(ValueError, match="unsafe"):
        archive_path(tmp_base, "../etc/passwd")


def test_absolute_filename(tmp_base):
    with pytest.raises(ValueError, match="unsafe"):
        archive_path(tmp_base, "/etc/passwd")


def test_null_byte(tmp_base):
    with pytest.raises(ValueError, match="unsafe"):
        archive_path(tmp_base, "file\x00.txt")


def test_empty_filename(tmp_base):
    with pytest.raises(ValueError, match="unsafe"):
        archive_path(tmp_base, "")


def test_double_dotdot_nested(tmp_base):
    with pytest.raises(ValueError, match="unsafe"):
        archive_path(tmp_base, "a/../../etc/passwd")


def test_symlink_escape(tmp_path, tmp_base):
    link = tmp_path / "escape"
    link.symlink_to(tmp_path)
    with pytest.raises(ValueError, match="unsafe"):
        archive_path(tmp_base, f"../{link.name}/secret")

