import os
import unittest

from archives import archive_path


class TestArchivePath(unittest.TestCase):

    def setUp(self):
        self.base = "/tmp/archive"

    # -- safe cases --

    def test_simple_filename(self):
        self.assertEqual(
            archive_path(self.base, "report.pdf"),
            os.path.join(self.base, "report.pdf"),
        )

    def test_filename_with_subdir(self):
        self.assertEqual(
            archive_path(self.base, "subdir/doc.txt"),
            os.path.join(self.base, "subdir", "doc.txt"),
        )

    def test_filename_with_extension(self):
        self.assertEqual(
            archive_path(self.base, "data.tar.gz"),
            os.path.join(self.base, "data.tar.gz"),
        )

    def test_filename_with_spaces_and_unicode(self):
        path = archive_path(self.base, "my file (1).csv")
        self.assertTrue(path.startswith(self.base))

    # -- unsafe cases --

    def test_empty_filename(self):
        with self.assertRaises(ValueError):
            archive_path(self.base, "")

    def test_none_filename(self):
        with self.assertRaises(ValueError):
            archive_path(self.base, None)

    def test_null_byte(self):
        with self.assertRaises(ValueError):
            archive_path(self.base, "file\x00.pdf")

    def test_absolute_path(self):
        with self.assertRaises(ValueError):
            archive_path(self.base, "/etc/passwd")

    def test_dot_dot_traversal(self):
        with self.assertRaises(ValueError):
            archive_path(self.base, "../secret")

    def test_nested_traversal(self):
        with self.assertRaises(ValueError):
