import os

def archive_path(base, filename):
    """Join base and filename safely, rejecting unsafe/untrusted names.

    Returns the resolved path under *base* when *filename* is safe.
    Raises ValueError for anything that would escape *base* or contains
    illegal characters.
    """
    if not filename:
        raise ValueError("filename must not be empty")

    # Reject null bytes (can truncate strings on some platforms / in C APIs)
    if "\x00" in filename:
        raise ValueError("filename must not contain null bytes")

    # Reject absolute paths (would bypass *base* entirely)
    if os.path.isabs(filename):
        raise ValueError("filename must not be an absolute path")

    # Reject components that try to climb out of *base*
    parts = filename.replace("\\", os.sep).split(os.sep)
    for part in parts:
        if part in (".", ""):
            continue
        if part == ".." or part.startswith(".."):
            raise ValueError(
                "filename must not contain path-traversal components"
            )

    # Resolve the final path and confirm it is still under *base*
    resolved = os.path.normpath(os.path.join(base, filename))
    base_resolved = os.path.normpath(os.path.abspath(base))

    if not resolved.startswith(base_resolved + os.sep) and resolved != base_resolved:
        raise ValueError(
            f"resolved path must stay under base; got {resolved!r}"
        )

    return resolved

